    const button=$('confirm-start-automation');button.onclick=action(async()=>{if(!button.isConnected)throw stale();button.disabled=true;try{await submitAutomation(project,options,scope,ticket,restartGeneration);if(current(scope)&&button.isConnected)$('portal-dialog').close();}finally{if(current(scope)&&button.isConnected)button.disabled=false;}});$('portal-dialog').showModal();
