    $('automation-mode').onchange=()=>{options.mode=$('automation-mode').value;updateAutomationControls();};$('open-agent-config').onclick=()=>showView('agents');$('automation-instructions').oninput=()=>options.instructions=$('automation-instructions').value;$('automation-provider').onchange=()=>options.provider=$('automation-provider').value;$('automation-model').onchange=()=>options.asr_model=$('automation-model').value;$('automation-repairs').onchange=()=>options.max_repairs=Number($('automation-repairs').value);
